style.css:
@-moz-document url-prefix("https://www.youtube.com/"), url-prefix("http://www.youtube.com/") {
/* =============================
   Gojo Theme — Variables
   ============================= */
:root {
  /* core palette */
  --gojo-bg: #0a0f1a;             /* deep night */
  --gojo-bg-2: #0f1726;           /* panel bg */
  --gojo-card: #111a2b;
  --gojo-text: #e8f1ff;
  --gojo-muted: #a9bddb;

  /* neon blues */
  --gojo-cyan: #15c6ff;
  --gojo-blue: #5aa8ff;
  --gojo-electric: #00e5ff;

  /* accents */
  --gojo-like: #39ffb9;
  --gojo-sub: #7aa7ff;
  --gojo-danger: #ff6b6b;

  /* effects */
  --gojo-radius: 16px;
  --gojo-shadow: 0 8px 28px rgba(12, 162, 255, 0.15), 0 2px 6px rgba(0,0,0,0.25);

  /* optional: change this to any Gojo wallpaper URL */
  --gojo-wallpaper: url("https://i.imgur.com/CFVw0fE.jpeg"); /* <- replace with your image link */
  --gojo-wallpaper-opacity: 0.14; /* 0 (off) — 0.3 (strong) */
}

/* =============================
   Global background + wallpaper
   ============================= */
ytd-app {
  background: var(--gojo-bg) !important;
}

html[dark] body::before,
ytd-app::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: var(--gojo-wallpaper);
  background-size: cover;
  background-position: center;
  opacity: var(--gojo-wallpaper-opacity);
  filter: saturate(1.1) contrast(1.05) blur(0px);
  z-index: 0;
}

/* put the app content above wallpaper */
#content,
ytd-page-manager,
ytd-app {
  position: relative;
  z-index: 1;
}

/* =============================
   Override YouTube spec vars
   (helps theme more deeply)
   ============================= */
html[dark] {
  --yt-spec-base-background: var(--gojo-bg) !important;
  --yt-spec-raised-background: var(--gojo-bg-2) !important;
  --yt-spec-menu-background: var(--gojo-card) !important;
  --yt-spec-additive-background: var(--gojo-bg-2) !important;

  --yt-spec-text-primary: var(--gojo-text) !important;
  --yt-spec-text-secondary: var(--gojo-muted) !important;
  --yt-spec-icon-active-other: var(--gojo-cyan) !important;
  --yt-spec-icon-inactive: #7f96b8 !important;

  --yt-spec-brand-background-primary: var(--gojo-bg) !important;
  --yt-spec-brand-button-background: var(--gojo-blue) !important;
  --yt-spec-static-brand-red: var(--gojo-electric) !important; /* affects progress bar etc */
}

/* =============================
   Cards, grids, chips
   ============================= */
ytd-rich-item-renderer,
ytd-compact-video-renderer,
ytd-playlist-renderer,
ytd-mini-guide-entry-renderer {
  background: linear-gradient(180deg, rgba(19,30,53,0.6), rgba(16,23,38,0.6)) !important;
  border: 1px solid rgba(90,168,255,0.18) !important;
  border-radius: var(--gojo-radius) !important;
  box-shadow: var(--gojo-shadow) !important;
  overflow: hidden;
}

ytd-rich-item-renderer:hover,
ytd-compact-video-renderer:hover {
  transform: translateY(-2px);
  transition: transform 160ms ease, box-shadow 160ms ease;
  box-shadow: 0 10px 34px rgba(0,229,255,0.18), 0 2px 10px rgba(0,0,0,0.35) !important;
}

/* Thumbnails rounded + subtle glow */
ytd-thumbnail yt-image img,
ytd-playlist-thumbnail img,
#thumbnail img {
  border-radius: 14px !important;
  box-shadow: 0 4px 18px rgba(21,198,255,0.12) !important;
}

/* Video titles */
#video-title,
a#video-title-link,
h3.ytd-compact-video-renderer a {
  color: var(--gojo-text) !important;
  text-shadow: 0 0 10px rgba(0,229,255,0.08);
  font-weight: 700 !important;
}

/* metadata text */
#metadata-line, #channel-name, #byline-container, .ytd-video-meta-block {
  color: var(--gojo-muted) !important;
}

/* Tags/chips */
yt-chip-cloud-chip-renderer {
  background: rgba(17,26,43,0.8) !important;
  border: 1px solid rgba(0,229,255,0.25) !important;
  border-radius: 999px !important;
}
yt-chip-cloud-chip-renderer:hover {
  box-shadow: 0 0 0 3px rgba(21,198,255,0.15) inset !important;
}

/* =============================
   Header & Search
   ============================= */
#masthead-container, tp-yt-app-header {
  background: linear-gradient(180deg, rgba(10,15,26,0.9), rgba(10,15,26,0.65)) !important;
  backdrop-filter: blur(6px);
  border-bottom: 1px solid rgba(0,229,255,0.18);
}

ytd-searchbox {
  background: var(--gojo-card) !important;
  border: 1px solid rgba(90,168,255,0.28) !important;
  border-radius: 999px !important;
  box-shadow: inset 0 0 0 2px rgba(21,198,255,0.08);
}
ytd-searchbox input {
  color: var(--gojo-text) !important;
}

/* =============================
   Buttons (like, subscribe, etc.)
   ============================= */
ytd-segmented-like-dislike-button-renderer button[aria-pressed="true"] {
  filter: drop-shadow(0 0 10px rgba(57,255,185,0.45));
  background: rgba(57,255,185,0.14) !important;
  border-radius: 12px !important;
}

ytd-subscribe-button-renderer tp-yt-paper-button,
ytd-subscribe-button-renderer yt-button-shape button,
ytd-subscribe-button-renderer .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled {
  background: linear-gradient(90deg, var(--gojo-blue), var(--gojo-electric)) !important;
  border-radius: 999px !important;
  color: #03121a !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  letter-spacing: .3px;
  box-shadow: 0 10px 28px rgba(0,229,255,0.25) !important;
}
ytd-subscribe-button-renderer .yt-spec-button-shape-next--tonal,
ytd-subscribe-button-renderer .yt-spec-button-shape-next--outline {
  border-color: rgba(0,229,255,0.5) !important;
  color: var(--gojo-cyan) !important;
}

/* =============================
   Watch page
   ============================= */
ytd-watch-flexy[theater] #player-theater-container,
ytd-watch-flexy #player-container {
  background: radial-gradient(1200px 600px at 50% -10%, rgba(0,229,255,0.15), rgba(10,15,26,0)) !important;
  border-radius: 18px !important;
  overflow: hidden !important;
  border: 1px solid rgba(0,229,255,0.18) !important;
}

/* player progress bar */
.ytp-progress-bar-container,
.ytp-swatch-background-color,
.ytp-play-progress {
  background: linear-gradient(90deg, var(--gojo-electric), var(--gojo-blue)) !important;
}
.ytp-load-progress {
  background: rgba(21,198,255,0.3) !important;
}

/* titles & channel on watch page */
ytd-video-primary-info-renderer h1,
ytd-watch-metadata #owner-name a {
  color: var(--gojo-text) !important;
  text-shadow: 0 0 12px rgba(0,229,255,0.08);
}

/* description & comments panes */
ytd-watch-metadata,
ytd-comments {
  background: linear-gradient(180deg, rgba(14,21,36,0.72), rgba(12,18,30,0.62)) !important;
  border: 1px solid rgba(90,168,255,0.18);
  border-radius: var(--gojo-radius);
  padding: 8px 12px;
  box-shadow: var(--gojo-shadow);
}

/* =============================
   Sidebars & guide
   ============================= */
#guide-content,
ytd-guide-renderer,
ytd-mini-guide-renderer {
  background: rgba(15,23,38,0.8) !important;
  border-right: 1px solid rgba(0,229,255,0.12);
}

/* =============================
   Scrollbar (Chromium)
   ============================= */
*::-webkit-scrollbar {
  height: 10px;
  width: 10px;
}
*::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--gojo-electric), var(--gojo-blue));
  border-radius: 999px;
  border: 2px solid var(--gojo-bg);
}
*::-webkit-scrollbar-track {
  background: rgba(5,8,14,0.6);
}

/* =============================
   Optional: hide Shorts row
   (uncomment to enable)
   ============================= */
/*
ytd-rich-shelf-renderer[is-shorts],
ytd-reel-shelf-renderer,
a[href*="/shorts"] {
  display: none !important;
}
*/

/* =============================
   Subtle animations
   ============================= */
a, button, yt-chip-cloud-chip-renderer, ytd-rich-item-renderer {
  transition: all 160ms ease-in-out !important;
}
}
